select case when credit_limit >= 12500 then 'high' when credit_limit >= 2600 then 'mid' else 'low' end as credit_limit_bucket, segment, concat_ws(', ', sort_array(collect_set(city))) as city_values, count(case when city = 'Singapore' then 1 end) as singapore_count from customers where email like '%@gmail.com' and signup_date < '2025-09-01' group by 1, 2 having count(case when city = 'Singapore' then 1 end) < 2;
